// Differential tests for uos/rt/date.hpp. Every expected value between the
// generated-vectors markers was produced by Bun 1.4.0 (TZ=UTC), except for
// parser rows updated to the standard date formats in DEVIATIONS-FROM-BUN.md.
#include "uos/rt/date.hpp"
#include "uos/rt/string.hpp"
#include "uos/rt/test.hpp"

#include <algorithm>
#include <array>
#include <cmath>
#include <limits>
#include <optional>
#include <string>
#include <string_view>

using namespace std::string_view_literals;
namespace rt = uos::rt;

namespace {
  constexpr double NaN = std::numeric_limits<double>::quiet_NaN();
  constexpr double Inf = std::numeric_limits<double>::infinity();

  // Same JS number: NaN equals NaN, and +0 differs from -0.
  bool sameNumber(double a, double b) { return (std::isnan(a) && std::isnan(b)) || (a == b && std::signbit(a) == std::signbit(b)); }
  std::string showNumber(double value) { return ::uos::rt::test::show(value); }

  void rowNumber(double actual, double expected, const char* text, std::size_t row, int line) {
    if (!sameNumber(actual, expected)) ::uos::rt::test::report(__FILE__, line, "row " + std::to_string(row) + ": " + text + "\n      actual:   " + showNumber(actual) + "\n      expected: " + showNumber(expected), false);
  }
  template <class A, class B>
  void rowEqual(const A& actual, const B& expected, const char* text, std::size_t row, int line) {
    if (!(actual == expected)) ::uos::rt::test::report(__FILE__, line, "row " + std::to_string(row) + ": " + text + "\n      actual:   " + ::uos::rt::test::show(actual) + "\n      expected: " + ::uos::rt::test::show(expected), false);
  }

  // "Name: message" of the rt::JsError the call throws, or "(no error)".
  template <class F>
  std::string thrownText(F&& call) {
    try {
      (void)call();
    } catch (const rt::JsError& error) {
      return error.toString();
    }
    return "(no error)";
  }
}

#define ROW_NUMBER(row, actual, expected) rowNumber((actual), (expected), #actual, (row), __LINE__)
#define ROW_EQ(row, actual, expected) rowEqual((actual), (expected), #actual, (row), __LINE__)

